type Op interface{ isOp() }
type Get struct{ Key string }
type Put struct{ Key string; Value int }
func (Get) isOp() {}
func (Put) isOp() {}
func Run(op Op, s Store) (int, error) {
    switch o := op.(type) {
    case Get: return s.Read(o.Key)
    case Put: return o.Value, s.Write(o.Key, o.Value)
    default:  return 0, fmt.Errorf("interpreter-as-data: unhandled %T", op)
    }
}
